        "file_path": "/private/tmp/rp1-evals/32de8016/workspace/src/validate-yaml.ts",
        "content": "/**\n * CLI entry point for YAML file validation.\n * Parses arguments, orchestrates validation, and formats output.\n */\n\nimport { validateYamlFile } from \"./yaml-validator\";\nimport type { ValidationResult } from \"./yaml-validator\";\n\n/**\n * Parse command-line arguments into file paths and flags.\n */\nexport function parseArgs(argv: string[]): { files: string[]; help: boolean } {\n  const args = argv.slice(2);\n  const help = args.includes(\"--help\") || args.includes(\"-h\");\n  const files = args.filter((arg) => arg !== \"--help\" && arg !== \"-h\");\n  return { files, help };\n}\n\n/**\n * Display usage information to stdout.\n */\nexport function showUsage(): void {\n  console.log(`Usage: bun run validate-yaml <file1.yaml> [file2.yaml ...]\n\nValidate one or more YAML files for syntax correctness.\n\nOptions:\n  --help, -h    Show this help message\n\nExample:\n  bun run validate-yaml config.yaml\n  bun run validate-yaml file1.yaml file2.yaml file3.yaml`);\n}\n\n/**\n * Format a validation result for terminal display.\n */\nexport function formatResult(result: ValidationResult): string {\n  if (result.valid) {\n    return `PASS  ${result.filePath}`;\n  }\n\n  let output = `FAIL  ${result.filePath}`;\n  if (result.error) {\n    output += `\\n  Error: ${result.error}`;\n  }\n  return output;\n}\n\n/**\n * Main orchestration: parse args, validate files, print results, set exit code.\n */\nasync function main(): Promise<void> {\n  const { files, help } = parseArgs(process.argv);\n\n  if (help) {\n    showUsage();\n    process.exit(0);\n  }\n\n  if (files.length === 0) {\n    showUsage();\n    process.exit(1);\n  }\n\n  let passed = 0;\n  let failed = 0;\n\n  for (const filePath of files) {\n    const result = await validateYamlFile(filePath);\n    console.log(formatResult(result));\n    if (result.valid) {\n      passed++;\n    } else {\n      failed++;\n    }\n  }\n\n  if (files.length > 1) {\n    console.log(`\\nResults: ${passed} passed, ${failed} failed`);\n  }\n\n  process.exit(failed > 0 ? 1 : 0);\n}\n\nmain();\n"
      },
