// HYP-001: Test whether Bun has built-in YAML parsing capability
// Tests: Bun.YAML.parse(), import from "bun" { YAML }

console.log("=== HYP-001: Bun Built-in YAML Parser ===\n");

// Test 1: Check if Bun.YAML exists
console.log("Test 1: Bun.YAML object exists?");
console.log("  typeof Bun.YAML:", typeof (Bun as any).YAML);
console.log("  Bun.YAML:", (Bun as any).YAML);

// Test 2: Check if Bun.YAML.parse is a function
console.log("\nTest 2: Bun.YAML.parse is a function?");
console.log("  typeof Bun.YAML.parse:", typeof (Bun as any).YAML?.parse);

// Test 3: Try parsing valid YAML
console.log("\nTest 3: Parse valid YAML");
try {
  const yaml = `
name: test-project
version: 1.0.0
database:
  host: localhost
  port: 5432
  credentials:
    username: admin
    password: secret
tags:
  - typescript
  - bun
  - yaml
enabled: true
count: 42
ratio: 3.14
nothing: null
`;
  const result = (Bun as any).YAML.parse(yaml);
  console.log("  Parsed successfully:", JSON.stringify(result, null, 2));
} catch (e: any) {
  console.log("  ERROR:", e.message);
}

// Test 4: Check if stringify exists
console.log("\nTest 4: Bun.YAML.stringify exists?");
console.log("  typeof Bun.YAML.stringify:", typeof (Bun as any).YAML?.stringify);

// Test 5: Try import { YAML } from "bun"
console.log("\nTest 5: import { YAML } from 'bun'");
try {
  const { YAML } = await import("bun");
  console.log("  YAML imported from 'bun':", typeof YAML);
  console.log("  YAML.parse:", typeof YAML?.parse);
} catch (e: any) {
  console.log("  ERROR:", e.message);
