/**
 * YAML validation logic module.
 * Provides functions to validate YAML file syntax using Bun built-in YAML support.
 */

/** Result of validating a single YAML file. */
export interface ValidationResult {
  filePath: string;
  valid: boolean;
  error?: string;
  line?: number;
  column?: number;
}

/**
 * Validate a YAML string for syntax correctness.
 * Splits multi-document YAML on `---` separators and validates each segment.
 */
export function validateYamlContent(
  content: string,
  filePath: string,
): ValidationResult {
  if (content.trim().length === 0) {
    return { filePath, valid: true };
  }

  const documents = content.split(/^---$/m).filter((s) => s.trim().length > 0);

  for (const doc of documents) {
    try {
      Bun.YAML.parse(doc);
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Unknown YAML parse error";
      return { filePath, valid: false, error: message };
    }
  }

  return { filePath, valid: true };
}

/**
 * Read a file and validate its contents as YAML.
 */
export async function validateYamlFile(
  filePath: string,
): Promise<ValidationResult> {
  let content: string;
  try {
    content = await Bun.file(filePath).text();
  } catch {
    return {
      filePath,
      valid: false,
      error: `File not found or unreadable: ${filePath}`,
    };
  }

  return validateYamlContent(content, filePath);
}

