/**
 * CLI entry point for YAML file validation.
 * Parses arguments, orchestrates validation, and formats output.
 */

import { validateYamlFile } from "./yaml-validator";
import type { ValidationResult } from "./yaml-validator";

/**
 * Parse command-line arguments into file paths and flags.
 */
export function parseArgs(argv: string[]): { files: string[]; help: boolean } {
  const args = argv.slice(2);
  const help = args.includes("--help") || args.includes("-h");
  const files = args.filter((arg) => arg !== "--help" && arg !== "-h");
  return { files, help };
}

/**
 * Display usage information to stdout.
 */
export function showUsage(): void {
  console.log(`Usage: bun run validate-yaml <file1.yaml> [file2.yaml ...]

Validate one or more YAML files for syntax correctness.

Options:
  --help, -h    Show this help message

Example:
  bun run validate-yaml config.yaml
  bun run validate-yaml file1.yaml file2.yaml file3.yaml`);
}

/**
 * Format a validation result for terminal display.
 */
export function formatResult(result: ValidationResult): string {
  if (result.valid) {
    return `PASS  ${result.filePath}`;
  }

  let output = `FAIL  ${result.filePath}`;
  if (result.error) {
    output += `\n  Error: ${result.error}`;
  }
  return output;
}

/**
 * Main orchestration: parse args, validate files, print results, set exit code.
 */
async function main(): Promise<void> {
  const { files, help } = parseArgs(process.argv);

  if (help) {
    showUsage();
    process.exit(0);
  }

  if (files.length === 0) {
    showUsage();
    process.exit(1);
  }

  let passed = 0;
  let failed = 0;

  for (const filePath of files) {
    const result = await validateYamlFile(filePath);
    console.log(formatResult(result));
    if (result.valid) {
      passed++;
    } else {
      failed++;
    }
  }

  if (files.length > 1) {
    console.log(`\nResults: ${passed} passed, ${failed} failed`);
  }

  process.exit(failed > 0 ? 1 : 0);
}

main();

import { describe, expect, test, afterAll } from "bun:test";
import { join } from "path";
import { tmpdir } from "os";
import { unlinkSync } from "fs";
import { validateYamlContent, validateYamlFile } from "./yaml-validator";

const tempFiles: string[] = [];

function tempPath(name: string): string {
  const filePath = join(tmpdir(), `yaml-validator-test-${Date.now()}-${name}`);
  tempFiles.push(filePath);
  return filePath;
}

afterAll(() => {
  for (const f of tempFiles) {
    try {
      unlinkSync(f);
    } catch {
      // already cleaned up
    }
  }
});

describe("yaml-validator", () => {
  describe("validateYamlContent", () => {
    test("returns valid for correct YAML", () => {
      const content = "name: Alice\nage: 30\n";
      const result = validateYamlContent(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.filePath).toBe("test.yaml");
      expect(result.error).toBeUndefined();
    });

    test("returns valid for empty content", () => {
      const result = validateYamlContent("", "empty.yaml");
      expect(result.valid).toBe(true);
      expect(result.filePath).toBe("empty.yaml");
    });

    test("returns valid for whitespace-only content", () => {
      const result = validateYamlContent("   \n  \n  ", "whitespace.yaml");
      expect(result.valid).toBe(true);
      expect(result.filePath).toBe("whitespace.yaml");
    });

    test("returns invalid with error details for malformed YAML", () => {
      const content = "key: value\n  bad:\nindent: broken: here";
      const result = validateYamlContent(content, "bad.yaml");
      expect(result.valid).toBe(false);
      expect(result.filePath).toBe("bad.yaml");
      expect(result.error).toBeDefined();
      expect(typeof result.error).toBe("string");
      expect(result.error!.length).toBeGreaterThan(0);
    });

    test("error messages are generic with no line/column info", () => {
      const content = ":\n  - invalid: [yaml\n  missing: bracket";
      const result = validateYamlContent(content, "generic-error.yaml");
      expect(result.valid).toBe(false);
      expect(result.line).toBeUndefined();
      expect(result.column).toBeUndefined();
    });

    test("validates all documents in multi-document YAML", () => {
      const content = "name: first\n---\nname: second\n---\nname: third\n";
      const result = validateYamlContent(content, "multi.yaml");
      expect(result.valid).toBe(true);
      expect(result.filePath).toBe("multi.yaml");
    });

    test("returns invalid if any document in multi-doc YAML is malformed", () => {
      const content = "name: valid\n---\n: [bad\n  yaml:\n---\nname: also-valid\n";
      const result = validateYamlContent(content, "multi-bad.yaml");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });
  });

  describe("validateYamlFile", () => {
    test("returns valid for a valid YAML file", async () => {
      const filePath = tempPath("valid.yaml");
      await Bun.write(filePath, "key: value\nlist:\n  - one\n  - two\n");
      const result = await validateYamlFile(filePath);
      expect(result.valid).toBe(true);
      expect(result.filePath).toBe(filePath);
      expect(result.error).toBeUndefined();
    });

    test("returns invalid for an invalid YAML file", async () => {
      const filePath = tempPath("invalid.yaml");
      await Bun.write(filePath, "key: value\n  bad:\nindent: broken: here");
      const result = await validateYamlFile(filePath);
      expect(result.valid).toBe(false);
      expect(result.filePath).toBe(filePath);
      expect(result.error).toBeDefined();
      expect(result.error!.length).toBeGreaterThan(0);
    });

    test("returns error for non-existent file path", async () => {
      const filePath = "/tmp/yaml-validator-test-does-not-exist-99999.yaml";
      const result = await validateYamlFile(filePath);
      expect(result.valid).toBe(false);
      expect(result.filePath).toBe(filePath);
      expect(result.error).toContain("File not found or unreadable");
    });

    test("returns valid for an empty file", async () => {
      const filePath = tempPath("empty.yaml");
      await Bun.write(filePath, "");
      const result = await validateYamlFile(filePath);
      expect(result.valid).toBe(true);
      expect(result.filePath).toBe(filePath);
    });
  });
});

